function(container, apiUrl, tables) {
  const tbody = container.querySelector("#history-tbody");
  const pageSize = 20;
  let currentPage = 1;
  let totalPages = 1;
  let allHistories = [];
  let filteredHistories = [];

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    const users = await window.aivicApi.list(0); // ログインユーザーテーブル
    const userSelect = container.querySelector("#user-filter");
    if (users) {
      users.forEach(user => {
        const option = document.createElement("option");
        option.value = user.ユーザーID;
        option.textContent = user.ユーザー名;
        userSelect.appendChild(option);
      });
    }
  }

  // 操作履歴一覧の再描画
  function renderHistories(histories) {
    const startIndex = (currentPage - 1) * pageSize;
    const endIndex = startIndex + pageSize;
    const pageHistories = histories.slice(startIndex, endIndex);

    tbody.innerHTML = pageHistories.map(history => `
      <tr data-id="${history.操作履歴ID}">
        <td>${formatDateTime(history.操作日時)}</td>
        <td>${getUserName(history.ユーザーID)}</td>
        <td>${history.操作種別 || ""}</td>
        <td>${history.操作画面 || ""}</td>
        <td>${history.IPアドレス || ""}</td>
        <td><span class="status-badge ${getResultClass(history.処理結果)}">${history.処理結果 || ""}</span></td>
        <td>${history.処理時間 ? history.処理時間 + "ms" : ""}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${history.操作履歴ID}">詳細</button>
        </td>
      </tr>
    `).join("");

    updatePagination(histories.length);
  }

  // 日時フォーマット
  function formatDateTime(dateTime) {
    if (!dateTime) return "";
    const date = new Date(dateTime);
    return date.toLocaleString("ja-JP");
  }

  // ユーザー名取得
  function getUserName(userId) {
    if (!userId || !tables[0]) return "";
    const user = tables[0].records.find(u => u.ユーザーID === userId);
    return user ? user.ユーザー名 : "";
  }

  // 処理結果のクラス取得
  function getResultClass(result) {
    switch(result) {
      case "成功": return "success";
      case "失敗": return "error";
      case "エラー": return "error";
      default: return "";
    }
  }

  // ページネーション更新
  function updatePagination(totalCount) {
    totalPages = Math.ceil(totalCount / pageSize);
    container.querySelector("#page-info").textContent = `${currentPage} / ${totalPages}`;
    container.querySelector("#btn-prev").disabled = currentPage <= 1;
    container.querySelector("#btn-next").disabled = currentPage >= totalPages;
  }

  // 検索フィルター適用
  function applyFilters() {
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const userId = container.querySelector("#user-filter").value;
    const operationType = container.querySelector("#operation-type-filter").value;
    const screenName = container.querySelector("#screen-search").value.toLowerCase();
    const ipAddress = container.querySelector("#ip-search").value;
    const result = container.querySelector("#result-filter").value;

    // 日付範囲バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      showError("開始日は終了日より前の日付を入力してください");
      return;
    }

    // IPアドレスバリデーション
    if (ipAddress && !isValidIpAddress(ipAddress)) {
      showError("正しいIPアドレス形式で入力してください");
      return;
    }

    filteredHistories = allHistories.filter(history => {
      // 日付範囲フィルター
      if (startDate && new Date(history.操作日時) < new Date(startDate)) return false;
      if (endDate && new Date(history.操作日時) > new Date(endDate + " 23:59:59")) return false;

      // ユーザーフィルター
      if (userId && history.ユーザーID !== userId) return false;

      // 操作種別フィルター
      if (operationType && history.操作種別 !== operationType) return false;

      // 画面名・機能名検索
      if (screenName && !history.操作画面?.toLowerCase().includes(screenName)) return false;

      // IPアドレス検索
      if (ipAddress && history.IPアドレス !== ipAddress) return false;

      // 処理結果フィルター
      if (result && history.処理結果 !== result) return false;

      return true;
    });

    currentPage = 1;
    renderHistories(filteredHistories);

    if (filteredHistories.length === 0) {
      showError("該当する操作履歴が見つかりませんでした");
    }
  }

  // IPアドレスバリデーション
  function isValidIpAddress(ip) {
    // IPv4の基本的なバリデーション
    const ipv4Regex = /^(\d{1,3}\.){3}\d{1,3}$/;
    // IPv6の基本的なバリデーション
    const ipv6Regex = /^([0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$|^::1$|^::$/;

    if (ipv4Regex.test(ip)) {
      const parts = ip.split('.');
      return parts.every(part => parseInt(part) >= 0 && parseInt(part) <= 255);
    }

    return ipv6Regex.test(ip);
  }

  // エラーメッセージ表示
  function showError(message) {
    const existingError = container.querySelector(".error-message");
    if (existingError) existingError.remove();

    const errorDiv = document.createElement("div");
    errorDiv.className = "error-message";
    errorDiv.textContent = message;
    container.querySelector(".search-section").appendChild(errorDiv);

    setTimeout(() => errorDiv.remove(), 5000);
  }

  // 成功メッセージ表示
  function showSuccess(message) {
    const existingSuccess = container.querySelector(".success-message");
    if (existingSuccess) existingSuccess.remove();

    const successDiv = document.createElement("div");
    successDiv.className = "success-message";
    successDiv.textContent = message;
    container.querySelector(".search-section").appendChild(successDiv);

    setTimeout(() => successDiv.remove(), 3000);
  }

  // CSV出力
  function exportToCsv() {
    if (filteredHistories.length === 0) {
      showError("出力可能なデータがありません");
      return;
    }

    const headers = ["操作日時", "ユーザー名", "操作種別", "操作画面", "操作対象テーブル", "操作対象ID", "操作内容", "IPアドレス", "ユーザーエージェント", "処理結果", "エラーメッセージ", "処理時間"];

    const csvContent = [
      headers.join(","),
      ...filteredHistories.map(history => [
        `"${formatDateTime(history.操作日時)}"`,
        `"${getUserName(history.ユーザーID)}"`,
        `"${history.操作種別 || ""}"`,
        `"${history.操作画面 || ""}"`,
        `"${history.操作対象テーブル || ""}"`,
        `"${history.操作対象ID || ""}"`,
        `"${(history.操作内容 || "").replace(/"/g, '""')}"`,
        `"${history.IPアドレス || ""}"`,
        `"${(history.ユーザーエージェント || "").replace(/"/g, '""')}"`,
        `"${history.処理結果 || ""}"`,
        `"${(history.エラーメッセージ || "").replace(/"/g, '""')}"`,
        `"${history.処理時間 || ""}"`
      ].join(","))
    ].join("\n");

    const bom = "\uFEFF";
    const blob = new Blob([bom + csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `操作履歴_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();

    showSuccess("CSVファイルをダウンロードしました");
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    const history = allHistories.find(h => h.操作履歴ID === historyId);
    if (!history) return;

    container.querySelector("#detail-datetime").textContent = formatDateTime(history.操作日時);
    container.querySelector("#detail-user").textContent = getUserName(history.ユーザーID);
    container.querySelector("#detail-operation").textContent = history.操作種別 || "";
    container.querySelector("#detail-screen").textContent = history.操作画面 || "";
    container.querySelector("#detail-table").textContent = history.操作対象テーブル || "";
    container.querySelector("#detail-target-id").textContent = history.操作対象ID || "";
    container.querySelector("#detail-content").textContent = history.操作内容 || "";
    container.querySelector("#detail-ip").textContent = history.IPアドレス || "";
    container.querySelector("#detail-user-agent").textContent = history.ユーザーエージェント || "";
    container.querySelector("#detail-result").textContent = history.処理結果 || "";
    container.querySelector("#detail-time").textContent = history.処理時間 ? history.処理時間 + "ms" : "";
    container.querySelector("#detail-error").textContent = history.エラーメッセージ || "";

    container.querySelector("#detail-modal").classList.remove("hidden");
  }

  // 初期データ読み込み
  async function loadData() {
    const histories = await window.aivicApi.list(12); // システム操作履歴テーブル
    if (histories) {
      allHistories = histories;
      filteredHistories = histories;
      renderHistories(filteredHistories);
    } else {
      allHistories = tables[12]?.records || [];
      filteredHistories = allHistories;
      renderHistories(filteredHistories);
    }
  }

  // イベントリスナー設定
  container.querySelector("#btn-search").addEventListener("click", applyFilters);

  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#start-date").value = "";
    container.querySelector("#end-date").value = "";
    container.querySelector("#user-filter").value = "";
    container.querySelector("#operation-type-filter").value = "";
    container.querySelector("#screen-search").value = "";
    container.querySelector("#ip-search").value = "";
    container.querySelector("#result-filter").value = "";

    filteredHistories = allHistories;
    currentPage = 1;
    renderHistories(filteredHistories);
  });

  container.querySelector("#btn-csv-export").addEventListener("click", exportToCsv);

  container.querySelector("#btn-prev").addEventListener("click", () => {
    if (currentPage > 1) {
      currentPage--;
      renderHistories(filteredHistories);
    }
  });

  container.querySelector("#btn-next").addEventListener("click", () => {
    if (currentPage < totalPages) {
      currentPage++;
      renderHistories(filteredHistories);
    }
  });

  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#detail-modal").classList.add("hidden");
  });

  container.querySelector("#detail-modal").addEventListener("click", (e) => {
    if (e.target.id === "detail-modal") {
      container.querySelector("#detail-modal").classList.add("hidden");
    }
  });

  // イベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  // 初期化
  loadUsers();
  loadData();

  // スタイル追加
  const style = document.createElement("style");
  style.textContent = `
    .status-badge {
      padding: 4px 8px;
      border-radius: 4px;
      font-size: 12px;
      font-weight: 500;
    }
    .status-badge.success {
      background: rgba(81, 207, 102, 0.1);
      color: #51cf66;
      border: 1px solid #51cf66;
    }
    .status-badge.error {
      background: rgba(255, 107, 107, 0.1);
      color: #ff6b6b;
      border: 1px solid #ff6b6b;
    }
  `;
  document.head.appendChild(style);
}
